(()=>{"use strict";document.addEventListener("click",e=>{const t=e.target.closest?e.target.closest("[data-finder-toggle]"):null,d=t?document.getElementById(t.getAttribute("data-finder-toggle")):null;d&&(d.hidden=!d.hidden,d.classList.toggle("in",!d.hidden),t.setAttribute("aria-expanded",d.hidden?"false":"true"))}),document.addEventListener("submit",e=>{e.target.querySelectorAll('#finder-search #advancedSearch select, [id^="mod-finder-searchform"] [id^="mod-finder-advanced"] select').forEach(e=>{e.value||(e.disabled=!0)})})})();